#!/usr/bin/env node
// catalog.mjs — regenerate models/library/manifest.json, models/CATALOG.md and CREDITS.md from every
// models/library/<id>/meta.json. Node 22+, no dependencies. Deterministic: entries sorted by id, no dates.
//
//   npm run library:catalog            write the three files
//   npm run library:catalog -- --check also fail when an entry is incomplete or a generated file is stale

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, "..", "..");
const LIB = path.join(ROOT, "models", "library");
const LICENSES = { CC0: "CC0 1.0", "CC-BY-4.0": "CC BY 4.0", "CC-BY-3.0": "CC BY 3.0" }; // free licences only
const ATTRIBUTION = new Set(["CC-BY-4.0", "CC-BY-3.0"]);

export function readEntries() {
  if (!fs.existsSync(LIB)) return [];
  return fs
    .readdirSync(LIB, { withFileTypes: true })
    .filter((d) => d.isDirectory() && fs.existsSync(path.join(LIB, d.name, "meta.json")))
    .map((d) => ({ id: d.name, dir: path.join(LIB, d.name), meta: JSON.parse(fs.readFileSync(path.join(LIB, d.name, "meta.json"), "utf8")) }))
    .sort((a, b) => (a.id < b.id ? -1 : 1));
}

/** Problems with one entry, as strings (empty = complete). */
export function entryProblems(e) {
  const m = e.meta;
  const p = [];
  if (m.id !== e.id) p.push(`meta.id "${m.id}" is not the folder name "${e.id}"`);
  for (const k of ["name", "height", "script", "colors", "materials", "category", "source"]) if (m[k] === undefined) p.push(`meta.${k} is missing`);
  const s = m.source || {};
  for (const k of ["license", "author", "page", "pack"]) if (!s[k]) p.push(`meta.source.${k} is missing`);
  if (s.license && !LICENSES[s.license]) p.push(`meta.source.license "${s.license}" is not one of ${Object.keys(LICENSES).join(", ")}`);
  const glb = path.join(e.dir, m.file || "model.glb");
  if (!fs.existsSync(glb)) p.push(`${path.relative(ROOT, glb)} is missing (run npm run library:ingest -- ${e.id})`);
  else if (m.sha256 && crypto.createHash("sha256").update(fs.readFileSync(glb)).digest("hex") !== m.sha256) p.push(`model.glb does not match meta.sha256 (re-run ingest)`);
  if (!m.ingest?.fetch?.sha256) p.push("meta.ingest.fetch.sha256 is missing: the download is not pinned");
  if (!fs.existsSync(path.join(e.dir, "preview.png"))) p.push(`preview.png is missing (run npm run library:check -- ${e.id})`);
  if (!m.qa) p.push(`meta.qa is missing (run npm run library:check -- ${e.id})`);
  return p;
}

const row = (cells) => `| ${cells.map((c) => String(c).replace(/\|/g, "\\|")).join(" | ")} |`;

export function render(entries) {
  const manifest = {
    note: "Generated by harness/library/catalog.mjs from models/library/*/meta.json. Do not edit by hand.",
    count: entries.length,
    entries: entries.map(({ id, meta: m }) => ({
      id,
      name: m.name,
      category: m.category,
      tags: m.tags || [],
      style: m.style || "",
      height: m.height,
      script: m.script,
      file: `models/library/${id}/${m.file || "model.glb"}`,
      bytes: m.bytes,
      sha256: m.sha256,
      triangles: m.triangles,
      bones: m.bones || 0,
      clips: Object.keys(m.clips || {}),
      source: m.source,
    })),
  };
  const byCat = new Map();
  for (const e of entries) {
    const c = e.meta.category || "other";
    if (!byCat.has(c)) byCat.set(c, []);
    byCat.get(c).push(e);
  }
  const md = [
    "# Model library catalog",
    "",
    "> Generated by `npm run library:catalog` from `models/library/*/meta.json`. Do not edit by hand.",
    "> How to use a library model: `harness/library/README.md`. Code models (`models/*.js`) are listed in `skills/html-anime-model/SKILL.md`.",
    "",
    `${entries.length} model${entries.length === 1 ? "" : "s"}, ${(entries.reduce((a, e) => a + (e.meta.bytes || 0), 0) / 1048576).toFixed(1)} MB of GLB.`,
    "",
  ];
  for (const [cat, list] of [...byCat].sort((a, b) => (a[0] < b[0] ? -1 : 1))) {
    md.push(`## ${cat}`, "", row(["preview", "id", "model", "height", "tris", "clips", "licence", "source"]), row(Array(8).fill("---")));
    for (const { id, meta: m } of list) {
      const clips = Object.keys(m.clips || {});
      md.push(
        row([
          `<img src="library/${id}/preview.png" width="240">`,
          `\`${id}\``,
          `${m.name}${m.style ? `<br>*${m.style}*` : ""}`,
          `${m.height} m`,
          m.triangles ?? "",
          clips.length ? clips.join(", ") : "-",
          LICENSES[m.source?.license] || m.source?.license || "",
          `[${m.source?.pack || m.source?.author}](${m.source?.page})`,
        ]),
      );
    }
    md.push("");
  }
  const credited = entries.filter((e) => ATTRIBUTION.has(e.meta.source?.license));
  const credits = [
    "# Credits",
    "",
    "> Generated by `npm run library:catalog`. Models under a licence that requires attribution are credited here.",
    "> Every other library model is CC0 (public domain); its author and source are still recorded in `models/CATALOG.md`.",
    "",
  ];
  if (!credited.length) credits.push("No attribution-licensed models yet.", "");
  for (const { id, meta: m } of credited)
    credits.push(`- **${m.name}** (\`models/library/${id}\`) by ${m.source.author}, ${LICENSES[m.source.license]} (${m.source.licenseUrl || "https://creativecommons.org/licenses/"}), from [${m.source.pack}](${m.source.page}).${m.source.changes ? ` Changes: ${m.source.changes}` : " Changes: normalized, recompressed, recoloured to a film palette."}`);
  if (credited.length) credits.push("");
  return { manifest: JSON.stringify(manifest, null, 2) + "\n", catalog: md.join("\n"), credits: credits.join("\n") };
}

function main() {
  const check = process.argv.includes("--check");
  const entries = readEntries();
  const out = render(entries);
  const files = { [path.join(LIB, "manifest.json")]: out.manifest, [path.join(ROOT, "models", "CATALOG.md")]: out.catalog, [path.join(ROOT, "CREDITS.md")]: out.credits };
  let bad = 0;
  for (const e of entries)
    for (const p of entryProblems(e)) {
      console.error(`${e.id}: ${p}`);
      bad++;
    }
  if (check) {
    for (const [f, text] of Object.entries(files))
      if (!fs.existsSync(f) || fs.readFileSync(f, "utf8") !== text) {
        console.error(`${path.relative(ROOT, f)} is stale: run npm run library:catalog`);
        bad++;
      }
  } else {
    fs.mkdirSync(LIB, { recursive: true });
    for (const [f, text] of Object.entries(files)) fs.writeFileSync(f, text);
    console.log(`catalog: ${entries.length} entries -> models/library/manifest.json, models/CATALOG.md, CREDITS.md`);
  }
  if (bad) process.exitCode = 1;
  else if (check) console.log(`catalog: ok (${entries.length} entries)`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
